"use client";

import {
  useId,
  useState,
  type ComponentProps,
  type CSSProperties,
} from "react";

import {
  formatBlockHeight,
  formatTimestamp,
  truncateMiddle,
} from "@/lib/bitcoin";
import { componentClasses } from "@/lib/utils";

import styles from "./longest-chain.module.css";
import type { BitcoinVisualProps } from "./shared";

export type ChainBranchState = "competing" | "stale" | "orphan";

export type LongestChainBlock = {
  /** Stable identifier used for selection state. */
  id: string;
  height: number;
  /** Optional real hash supplied by the caller. */
  hash?: string;
  timestamp?: number | Date;
  transactionCount?: number;
  miner?: string;
  /** Caller-supplied chainwork or decision note. */
  work?: string;
};

export type LongestChainBranch = {
  id: string;
  label: string;
  state: ChainBranchState;
  /**
   * Height on the canonical chain where this branch diverges. Leave empty for
   * an orphan whose parent is not known to the current view.
   */
  forkHeight?: number;
  /** Places the branch above or below the most-work path. @default "above" */
  direction?: "above" | "below";
  blocks: readonly LongestChainBlock[];
};

export type LongestChainProps = Omit<ComponentProps<"figure">, "children"> &
  BitcoinVisualProps & {
    canonical: readonly LongestChainBlock[];
    branches?: readonly LongestChainBranch[];
    /** Pauses the traveling chainwork signal. @default false */
    paused?: boolean;
    /** @default "Most-work chain" */
    title?: string;
    /** Accessible description of the represented fixture or network snapshot. */
    description?: string;
  };

type PositionedNode = {
  block: LongestChainBlock;
  branchId: string;
  branchLabel: string;
  direction: "main" | "above" | "below";
  state: "canonical" | "tip" | ChainBranchState;
  x: number;
  y: number;
};

type ChainNodeStyle = CSSProperties & {
  "--chain-x": string;
  "--chain-y": string;
};

const VIEWBOX_WIDTH = 1_000;
const VIEWBOX_HEIGHT = 360;
const MAIN_Y = 180;
const X_START = 88;
const X_END = 912;

function pathThrough(points: readonly { x: number; y: number }[]) {
  if (points.length === 0) return "";
  if (points.length === 1) {
    const point = points[0];
    return `M ${point.x - 54} ${point.y} L ${point.x} ${point.y}`;
  }

  return points.slice(1).reduce((path, point, index) => {
    const previous = points[index];
    const midpoint = (previous.x + point.x) / 2;
    return `${path} C ${midpoint} ${previous.y}, ${midpoint} ${point.y}, ${point.x} ${point.y}`;
  }, `M ${points[0].x} ${points[0].y}`);
}

function stateLabel(state: PositionedNode["state"]) {
  switch (state) {
    case "canonical":
      return "Most-work chain";
    case "tip":
      return "Canonical tip";
    case "competing":
      return "Competing fork";
    case "stale":
      return "Stale sibling";
    case "orphan":
      return "Orphan · parent unknown";
  }
}

export function LongestChain({
  canonical,
  branches = [],
  paused,
  title = "Most-work chain",
  description = "The branch with the greatest accumulated proof of work remains canonical.",
  unstyled,
  className,
  ...props
}: LongestChainProps) {
  const baseId = useId();
  const [hoveredId, setHoveredId] = useState<string | null>(null);
  const [pinnedId, setPinnedId] = useState<string | null>(null);
  const safeCanonical = canonical.filter((block) =>
    Number.isFinite(block.height),
  );
  const safeBranches = branches
    .map((branch) => ({
      ...branch,
      blocks: branch.blocks.filter((block) => Number.isFinite(block.height)),
    }))
    .filter((branch) => branch.blocks.length > 0);
  const allHeights = [
    ...safeCanonical.map((block) => block.height),
    ...safeBranches.flatMap((branch) =>
      branch.blocks.map((block) => block.height),
    ),
  ];
  const minHeight = Math.min(...allHeights);
  const maxHeight = Math.max(...allHeights);
  const heightRange =
    Number.isFinite(minHeight) && Number.isFinite(maxHeight)
      ? Math.max(1, maxHeight - minHeight)
      : 1;
  const xForHeight = (height: number) =>
    X_START + ((height - minHeight) / heightRange) * (X_END - X_START);

  const branchCounts = {
    above: safeBranches.filter(
      (branch) => (branch.direction ?? "above") === "above",
    ).length,
    below: safeBranches.filter(
      (branch) => (branch.direction ?? "above") === "below",
    ).length,
  };
  const directionIndexes = { above: 0, below: 0 };
  const canonicalNodes: PositionedNode[] = safeCanonical.map(
    (block, index) => ({
      block,
      branchId: "canonical",
      branchLabel: "Most-work chain",
      direction: "main",
      state:
        index === safeCanonical.length - 1
          ? ("tip" as const)
          : ("canonical" as const),
      x: xForHeight(block.height),
      y: MAIN_Y,
    }),
  );
  const branchNodes: PositionedNode[] = safeBranches.flatMap((branch) => {
    const direction = branch.direction ?? "above";
    const directionIndex = directionIndexes[direction]++;
    const directionCount = branchCounts[direction];
    const magnitude =
      directionCount <= 1
        ? 96
        : 88 + (directionIndex / (directionCount - 1)) * 52;
    const y = MAIN_Y + (direction === "above" ? -magnitude : magnitude);

    return branch.blocks.map((block) => ({
      block,
      branchId: branch.id,
      branchLabel: branch.label,
      direction,
      state: branch.state,
      x: xForHeight(block.height),
      y,
    }));
  });
  const nodes = [...canonicalNodes, ...branchNodes];

  const defaultNode =
    canonicalNodes[canonicalNodes.length - 1] ?? nodes[0];
  const activeId = hoveredId ?? pinnedId ?? defaultNode?.block.id ?? null;
  const activeNode =
    nodes.find((node) => node.block.id === activeId) ?? defaultNode;
  const canonicalPath = pathThrough(
    safeCanonical.map((block) => ({ x: xForHeight(block.height), y: MAIN_Y })),
  );

  return (
    <figure
      data-slot="longest-chain"
      data-paused={paused || undefined}
      data-unstyled={unstyled || undefined}
      aria-label={`${title}. ${description}`}
      className={componentClasses(unstyled, styles.figure, className)}
      {...props}
    >
      <figcaption className={componentClasses(unstyled, styles.header)}>
        <div>
          <span className={componentClasses(unstyled, styles.eyebrow)}>
            Consensus history
          </span>
          <strong>{title}</strong>
        </div>
        <p>{description}</p>
      </figcaption>

      <div className={componentClasses(unstyled, styles.legendRow)}>
        <ul aria-label="Chain state legend">
          {(
            [
              ["canonical", "Most-work chain"],
              ["competing", "Competing fork"],
              ["stale", "Stale sibling"],
              ["orphan", "Orphan · parent unknown"],
            ] as const
          ).map(([state, label]) => (
            <li key={state} data-state={state}>
              <i aria-hidden="true" />
              {label}
            </li>
          ))}
        </ul>
        <span>Bitcoin has no rewarded uncle state.</span>
      </div>

      <div className={componentClasses(unstyled, styles.viewport)}>
        <div className={componentClasses(unstyled, styles.canvas)}>
          <svg
            className={componentClasses(unstyled, styles.paths)}
            viewBox={`0 0 ${VIEWBOX_WIDTH} ${VIEWBOX_HEIGHT}`}
            preserveAspectRatio="none"
            fill="none"
            stroke="currentColor"
            strokeWidth="2"
            strokeLinecap="round"
            strokeLinejoin="round"
            aria-hidden="true"
          >
            <defs>
              <filter id={`${baseId}-glow`} x="-30%" y="-100%" width="160%" height="300%">
                <feGaussianBlur stdDeviation="8" />
              </filter>
            </defs>
            <path
              data-state="canonical-glow"
              d={canonicalPath}
              filter={`url(#${baseId}-glow)`}
            />
            <path data-state="canonical" d={canonicalPath} />
            <path
              data-state="signal"
              d={canonicalPath}
              pathLength="100"
            />
            {safeBranches.map((branch) => {
              const branchNodes = nodes.filter(
                (node) => node.branchId === branch.id,
              );
              const forkNode =
                branch.forkHeight === undefined
                  ? undefined
                  : safeCanonical.find(
                      (block) => block.height === branch.forkHeight,
                    );
              const points = [
                ...(forkNode
                  ? [{ x: xForHeight(forkNode.height), y: MAIN_Y }]
                  : []),
                ...branchNodes.map((node) => ({ x: node.x, y: node.y })),
              ];

              return (
                <path
                  key={branch.id}
                  data-state={branch.state}
                  data-disconnected={!forkNode || undefined}
                  d={pathThrough(points)}
                  pathLength="100"
                />
              );
            })}
          </svg>

          {nodes.map((node, index) => {
            const tooltipId = `${baseId}-node-${index}`;
            const isPinned = pinnedId === node.block.id;
            const nodeLabel = `${stateLabel(node.state)}, block ${formatBlockHeight(
              node.block.height,
            )}${node.block.miner ? `, mined by ${node.block.miner}` : ""}`;

            return (
              <div
                key={`${node.branchId}-${node.block.id}`}
                data-slot="chain-block"
                data-state={node.state}
                data-direction={node.direction}
                data-edge={
                  node.x === X_START
                    ? "start"
                    : node.x === X_END
                      ? "end"
                      : undefined
                }
                data-active={activeId === node.block.id || undefined}
                data-pinned={isPinned || undefined}
                className={componentClasses(unstyled, styles.node)}
                style={
                  {
                    "--chain-x": `${(node.x / VIEWBOX_WIDTH) * 100}%`,
                    "--chain-y": `${(node.y / VIEWBOX_HEIGHT) * 100}%`,
                  } as ChainNodeStyle
                }
                onMouseEnter={() => setHoveredId(node.block.id)}
                onMouseLeave={() => setHoveredId(null)}
              >
                <button
                  type="button"
                  aria-label={nodeLabel}
                  aria-describedby={unstyled ? undefined : tooltipId}
                  aria-pressed={isPinned}
                  onFocus={() => setHoveredId(node.block.id)}
                  onBlur={() => setHoveredId(null)}
                  onClick={() =>
                    setPinnedId((current) =>
                      current === node.block.id ? null : node.block.id,
                    )
                  }
                  onKeyDown={(event) => {
                    if (event.key === "Escape") {
                      setPinnedId(null);
                      setHoveredId(null);
                    }
                  }}
                >
                  <i aria-hidden="true" />
                  {unstyled ? (
                    <span>{formatBlockHeight(node.block.height)}</span>
                  ) : (
                    <>
                      <span className={styles.heightFull}>
                        {formatBlockHeight(node.block.height)}
                      </span>
                      <span aria-hidden="true" className={styles.heightShort}>
                        {String(node.block.height).slice(-3)}
                      </span>
                    </>
                  )}
                </button>
                <div
                  id={tooltipId}
                  role="tooltip"
                  hidden={unstyled || undefined}
                  className={componentClasses(unstyled, styles.tooltip)}
                >
                  <strong>{stateLabel(node.state)}</strong>
                  <span>{node.branchLabel}</span>
                  <small>Click to pin</small>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {activeNode ? (
        <aside
          data-slot="chain-block-metadata"
          data-state={activeNode.state}
          className={componentClasses(unstyled, styles.inspector)}
          aria-live="polite"
        >
          <header>
            <span>Selected block</span>
            <strong>{stateLabel(activeNode.state)}</strong>
          </header>
          <dl>
            <div>
              <dt>Height</dt>
              <dd>{formatBlockHeight(activeNode.block.height)}</dd>
            </div>
            <div>
              <dt>Branch</dt>
              <dd>{activeNode.branchLabel}</dd>
            </div>
            {activeNode.block.hash ? (
              <div>
                <dt>Hash</dt>
                <dd title={activeNode.block.hash}>
                  {truncateMiddle(activeNode.block.hash, 6, 6)}
                </dd>
              </div>
            ) : null}
            {activeNode.block.miner ? (
              <div>
                <dt>Miner</dt>
                <dd>{activeNode.block.miner}</dd>
              </div>
            ) : null}
            {activeNode.block.transactionCount !== undefined ? (
              <div>
                <dt>Transactions</dt>
                <dd>
                  {new Intl.NumberFormat("en-US").format(
                    activeNode.block.transactionCount,
                  )}
                </dd>
              </div>
            ) : null}
            {activeNode.block.timestamp ? (
              <div>
                <dt>Seen</dt>
                <dd>{formatTimestamp(activeNode.block.timestamp)}</dd>
              </div>
            ) : null}
            {activeNode.block.work ? (
              <div>
                <dt>Chainwork</dt>
                <dd>{activeNode.block.work}</dd>
              </div>
            ) : null}
          </dl>
        </aside>
      ) : null}

      <p className={componentClasses(unstyled, styles.note)}>
        <strong>Terminology:</strong> a valid sibling that loses the chainwork
        race is stale. “Uncle” is an Ethereum term; Bitcoin does not reward
        these blocks. An orphan has no known parent in the current view.
      </p>
    </figure>
  );
}

/* Hallmark · component: longest-chain illustrator · genre: modern-minimal · macrostructure: chain-race timeline
 * theme: Vercel monochrome + semantic chain-state accents
 * pre-emit critique: P5 H5 E5 S5 R5 V5
 * states: default · hover · focus · active · pinned · paused · reduced-motion
 * contrast: pass (46–50) · slop: pass (component scope)
 */

.figure {
  display: grid;
  min-width: 0;
  margin: 0;
  gap: var(--space-5);
  color: var(--color-ink);
  font-variant-numeric: tabular-nums;
}

.header {
  display: grid;
  grid-template-columns: minmax(0, 0.7fr) minmax(16rem, 1fr);
  align-items: end;
  gap: var(--space-8);
}

.header > div {
  display: grid;
  gap: var(--space-2);
}

.header strong {
  font-size: var(--text-xl);
  font-weight: 560;
  letter-spacing: -0.025em;
}

.eyebrow {
  color: var(--color-muted);
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.header p,
.note {
  max-width: 66ch;
  margin: 0;
  color: var(--color-muted);
  font-size: var(--text-xs);
  line-height: 1.6;
}

.legendRow {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding-block: var(--space-3);
  border-block: var(--rule-hair) solid var(--color-rule);
}

.legendRow ul {
  display: flex;
  min-width: 0;
  margin: 0;
  padding: 0;
  flex-wrap: wrap;
  gap: var(--space-3) var(--space-5);
  list-style: none;
}

.legendRow li,
.legendRow > span {
  display: inline-flex;
  align-items: center;
  gap: var(--space-2);
  color: var(--color-muted);
  font-size: 0.6875rem;
}

.legendRow li i {
  width: var(--space-4);
  height: var(--rule-hair);
  background: var(--chain-state-color);
  box-shadow: 0 0 var(--space-2) var(--chain-state-glow);
}

.legendRow li[data-state="canonical"] {
  --chain-state-color: var(--color-chain-canonical);
  --chain-state-glow: var(--color-chain-canonical-soft);
}

.legendRow li[data-state="competing"] {
  --chain-state-color: var(--color-chain-competing);
  --chain-state-glow: var(--color-chain-competing-soft);
}

.legendRow li[data-state="stale"] {
  --chain-state-color: var(--color-chain-stale);
  --chain-state-glow: var(--color-chain-stale-soft);
}

.legendRow li[data-state="orphan"] {
  --chain-state-color: var(--color-chain-orphan);
  --chain-state-glow: var(--color-chain-orphan-soft);
}

.legendRow > span {
  flex: 0 0 auto;
  font-family: var(--font-mono);
}

.viewport {
  min-width: 0;
  overflow: clip;
  border: var(--rule-hair) solid var(--color-rule-strong);
  border-radius: var(--radius-lg);
  background:
    linear-gradient(var(--color-rule-subtle) var(--rule-hair), transparent var(--rule-hair))
      0 25% / 100% 25%,
    var(--color-surface);
}

.canvas {
  position: relative;
  width: 100%;
  min-width: 0;
  height: clamp(20rem, 38vw, 27rem);
  isolation: isolate;
  overflow: hidden;
}

.paths {
  position: absolute;
  z-index: var(--z-canvas);
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
}

.paths path {
  fill: none;
  vector-effect: non-scaling-stroke;
  stroke: var(--chain-state-color);
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: 2;
}

.paths path[data-state="canonical"],
.paths path[data-state="canonical-glow"],
.paths path[data-state="signal"] {
  --chain-state-color: var(--color-chain-canonical);
}

.paths path[data-state="canonical-glow"] {
  stroke: var(--color-chain-canonical-soft);
  stroke-width: 18;
  opacity: 0.7;
}

.paths path[data-state="signal"] {
  stroke: var(--color-chain-signal);
  stroke-dasharray: 1 99;
  stroke-width: 5;
  animation: chain-signal var(--dur-relay) linear infinite;
}

.paths path[data-state="competing"] {
  --chain-state-color: var(--color-chain-competing);
}

.paths path[data-state="stale"] {
  --chain-state-color: var(--color-chain-stale);
}

.paths path[data-state="orphan"] {
  --chain-state-color: var(--color-chain-orphan);
  stroke-dasharray: 2 7;
}

.paths path[data-disconnected="true"] {
  stroke-dasharray: 2 8;
  opacity: 0.7;
}

.node {
  --chain-state-color: var(--color-chain-canonical);
  --chain-state-soft: var(--color-chain-canonical-soft);
  position: absolute;
  z-index: var(--z-content);
  top: var(--chain-y);
  left: var(--chain-x);
  transform: translate(-50%, -50%);
}

.node[data-state="tip"] {
  --chain-state-color: var(--color-chain-canonical);
  --chain-state-soft: var(--color-chain-canonical-soft);
}

.node[data-state="competing"] {
  --chain-state-color: var(--color-chain-competing);
  --chain-state-soft: var(--color-chain-competing-soft);
}

.node[data-state="stale"] {
  --chain-state-color: var(--color-chain-stale);
  --chain-state-soft: var(--color-chain-stale-soft);
}

.node[data-state="orphan"] {
  --chain-state-color: var(--color-chain-orphan);
  --chain-state-soft: var(--color-chain-orphan-soft);
}

.node button {
  display: grid;
  min-width: clamp(2.75rem, 7.5vw, 4.8rem);
  min-height: clamp(3rem, 5.5vw, 3.5rem);
  padding: var(--space-2);
  place-items: center;
  gap: var(--space-1);
  border: var(--rule-hair) solid var(--chain-state-color);
  border-radius: var(--radius-sm);
  outline: 2px solid transparent;
  outline-offset: 3px;
  cursor: pointer;
  appearance: none;
  color: var(--color-ink);
  background: var(--color-surface-raised);
  box-shadow:
    0 0 0 var(--rule-hair) var(--color-paper),
    0 0 var(--space-4) var(--chain-state-soft);
  font: inherit;
  transition:
    transform var(--dur-base) var(--ease-out),
    border-color var(--dur-fast) var(--ease-out),
    background-color var(--dur-fast) var(--ease-out),
    box-shadow var(--dur-base) var(--ease-out);
}

.node button i {
  width: 1.5rem;
  height: var(--space-1);
  border-radius: var(--radius-full);
  background: var(--chain-state-color);
  box-shadow: 0 0 var(--space-2) var(--chain-state-soft);
}

.node button span {
  font-family: var(--font-mono);
  font-size: 0.6875rem;
}

.heightShort {
  display: none;
}

.node button:focus-visible {
  outline-color: var(--color-focus);
}

.node button:active {
  transform: translateY(1px);
  background: var(--color-surface-active);
}

.node button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.node[data-active="true"] button,
.node[data-pinned="true"] button {
  transform: translateY(calc(var(--space-1) * -1));
  border-width: 2px;
  background: var(--color-surface-hover);
  box-shadow:
    0 0 0 var(--rule-hair) var(--color-paper),
    0 0 var(--space-6) var(--chain-state-soft);
}

.tooltip {
  position: absolute;
  z-index: var(--z-toolbar);
  bottom: calc(100% + var(--space-3));
  left: 50%;
  display: grid;
  width: 10.5rem;
  padding: var(--space-3);
  gap: var(--space-1);
  transform: translate(-50%, var(--space-1));
  border: var(--rule-hair) solid var(--color-rule-strong);
  border-radius: var(--radius-sm);
  color: var(--color-ink);
  background: var(--color-surface-raised);
  opacity: 0;
  pointer-events: none;
  visibility: hidden;
  transition:
    opacity var(--dur-base) var(--ease-out) 900ms,
    transform var(--dur-base) var(--ease-out) 900ms,
    visibility 0s linear 900ms;
}

.node[data-direction="above"] .tooltip {
  top: calc(100% + var(--space-3));
  bottom: auto;
  transform: translate(-50%, calc(var(--space-1) * -1));
}

.node[data-edge="start"] .tooltip {
  right: auto;
  left: 0;
  transform: translate(0, var(--space-1));
}

.node[data-edge="end"] .tooltip {
  right: 0;
  left: auto;
  transform: translate(0, var(--space-1));
}

.node[data-direction="above"][data-edge="start"] .tooltip,
.node[data-direction="above"][data-edge="end"] .tooltip {
  transform: translate(0, calc(var(--space-1) * -1));
}

.tooltip strong,
.tooltip span,
.tooltip small {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tooltip strong {
  font-size: 0.6875rem;
  font-weight: 560;
}

.tooltip span,
.tooltip small {
  color: var(--color-muted);
  font-family: var(--font-mono);
  font-size: 0.625rem;
}

.node:focus-within .tooltip,
.node[data-pinned="true"] .tooltip {
  transform: translate(-50%, 0);
  opacity: 1;
  visibility: visible;
  transition-delay: 0s;
}

.node[data-edge="start"]:focus-within .tooltip,
.node[data-edge="end"]:focus-within .tooltip,
.node[data-edge="start"][data-pinned="true"] .tooltip,
.node[data-edge="end"][data-pinned="true"] .tooltip {
  transform: translate(0, 0);
}

.inspector {
  display: grid;
  min-width: 0;
  padding: var(--space-4);
  grid-template-columns: minmax(10rem, 14rem) minmax(0, 1fr);
  gap: var(--space-3);
  border: var(--rule-hair) solid var(--chain-state-color);
  border-radius: var(--radius-md);
  color: var(--color-ink);
  background: var(--color-surface-raised);
  box-shadow: 0 0 var(--space-6) var(--chain-state-soft);
}

.inspector[data-state="canonical"],
.inspector[data-state="tip"] {
  --chain-state-color: var(--color-chain-canonical);
  --chain-state-soft: var(--color-chain-canonical-soft);
}

.inspector[data-state="competing"] {
  --chain-state-color: var(--color-chain-competing);
  --chain-state-soft: var(--color-chain-competing-soft);
}

.inspector[data-state="stale"] {
  --chain-state-color: var(--color-chain-stale);
  --chain-state-soft: var(--color-chain-stale-soft);
}

.inspector[data-state="orphan"] {
  --chain-state-color: var(--color-chain-orphan);
  --chain-state-soft: var(--color-chain-orphan-soft);
}

.inspector header,
.inspector dl > div {
  display: flex;
  min-width: 0;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}

.inspector header {
  padding-bottom: var(--space-3);
  align-items: flex-start;
  justify-content: center;
  flex-direction: column;
  border-right: var(--rule-hair) solid var(--color-rule);
}

.inspector header span,
.inspector dt {
  color: var(--color-muted);
  font-size: 0.6875rem;
}

.inspector header strong {
  color: var(--color-ink);
  font-size: 0.6875rem;
  font-weight: 560;
}

.inspector dl {
  display: grid;
  margin: 0;
  padding-left: var(--space-3);
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-2);
}

.inspector dd {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  font-family: var(--font-mono);
  font-size: 0.6875rem;
  text-align: right;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.note {
  padding-left: var(--space-4);
  border-left: 2px solid var(--color-chain-canonical);
}

.note strong {
  margin-right: var(--space-1);
  color: var(--color-ink);
  font-weight: 560;
}

@media (hover: hover) and (pointer: fine) {
  .node:hover button {
    transform: translateY(calc(var(--space-1) * -1));
    background: var(--color-surface-hover);
    box-shadow:
      0 0 0 var(--rule-hair) var(--color-paper),
      0 0 var(--space-6) var(--chain-state-soft);
  }

  .node:hover .tooltip {
    transform: translate(-50%, 0);
    opacity: 1;
    visibility: visible;
  }

  .node[data-edge="start"]:hover .tooltip,
  .node[data-edge="end"]:hover .tooltip {
    transform: translate(0, 0);
  }
}

[data-paused="true"] .paths path[data-state="signal"] {
  animation-play-state: paused;
}

@keyframes chain-signal {
  from {
    stroke-dashoffset: 100;
  }
  to {
    stroke-dashoffset: 0;
  }
}

@media (max-width: 48rem) {
  .header {
    grid-template-columns: 1fr;
    gap: var(--space-3);
  }

  .legendRow {
    align-items: flex-start;
    flex-direction: column;
  }

  .node button {
    padding: var(--space-1);
  }

  .node button span {
    font-size: 0.5625rem;
  }

  .inspector {
    grid-template-columns: 1fr;
  }

  .inspector header {
    padding-bottom: var(--space-3);
    border-right: 0;
    border-bottom: var(--rule-hair) solid var(--color-rule);
  }

  .inspector dl {
    padding-left: 0;
    grid-template-columns: 1fr;
  }
}

@media (max-width: 32rem) {
  .node button {
    min-width: var(--space-10);
    padding: var(--space-1) 0;
  }

  .heightFull {
    display: none;
  }

  .heightShort {
    display: inline;
  }
}

@media (prefers-reduced-motion: reduce) {
  .paths path[data-state="signal"] {
    display: none;
    animation: none;
  }

  .node button,
  .tooltip {
    transition: none;
  }
}
